"use client"

import * as React from "react"
import * as TabsPrimitive from "@radix-ui/react-tabs"

import { cn } from "@/lib/utils"
import { roll } from "@/lib/0db/roll"

function Tabs({ className, ...props }: React.ComponentProps<typeof TabsPrimitive.Root>) {
  return <TabsPrimitive.Root data-slot="tabs" className={cn("db-tabs-root", className)} {...props} />
}

/**
 * Sets where the line goes: --x (left), --r (right inset) and --y (lift to the
 * last row when the words wrap), measured from the active tab. data-dir says
 * which way it moved so the leading edge can go first. Physical measurements,
 * so right-to-left needs nothing more.
 */
function useFollow() {
  const list = React.useRef<HTMLDivElement | null>(null)
  React.useLayoutEffect(() => {
    const el = list.current
    if (!el) return
    let ready = false
    const follow = () => {
      const on = el.querySelector<HTMLElement>('[role="tab"][data-state="active"]')
      if (!on) return
      const b = el.getBoundingClientRect()
      const r = on.getBoundingClientRect()
      const lastRow = Math.max(...[...el.querySelectorAll('[role="tab"]')].map((t) => t.getBoundingClientRect().bottom))
      const was = parseFloat(el.style.getPropertyValue("--x")) || 0
      el.dataset.dir = r.left - b.left >= was ? "right" : "left"
      el.style.setProperty("--x", `${r.left - b.left}px`)
      el.style.setProperty("--r", `${b.right - r.right}px`)
      el.style.setProperty("--y", `${r.bottom - lastRow}px`)
    }
    follow()
    // Nothing glides until the person has chosen: the first place is just where it starts.
    const chose = new MutationObserver(() => {
      if (!ready) el.setAttribute("data-ready", "")
      ready = true
      follow()
    })
    chose.observe(el, { attributes: true, attributeFilter: ["data-state"], subtree: true })
    const resize = new ResizeObserver(follow)
    resize.observe(el)
    el.querySelectorAll('[role="tab"]').forEach((t) => resize.observe(t))
    document.fonts?.ready.then(follow)
    return () => {
      chose.disconnect()
      resize.disconnect()
    }
  }, [])
  return (node: HTMLDivElement | null) => {
    list.current = node
  }
}

/** Words with a hairline beneath; a line slides to the one in view, leading edge first. */
// ponytail: takes no ref of its own; the hook owns it. Add a merged ref if someone needs the list element.
function TabsList({ className, children, ...props }: Omit<React.ComponentProps<typeof TabsPrimitive.List>, "ref">) {
  const follow = useFollow()
  return (
    <TabsPrimitive.List
      ref={follow}
      data-slot="tabs-list"
      className={cn("db-tabs", className)}
      {...props}
    >
      {children}
      <span data-slot="tabs-line" className="db-tabs-line" aria-hidden="true" />
    </TabsPrimitive.List>
  )
}

type TabsTriggerProps = React.ComponentProps<typeof TabsPrimitive.Trigger> & {
  /** How many things are behind this tab, raised beside its name. */
  count?: number | string
}

function TabsTrigger({ className, count, children, ...props }: TabsTriggerProps) {
  return (
    <TabsPrimitive.Trigger data-slot="tabs-trigger" className={className} {...props}>
      {children}
      {count !== undefined ? <sup>{count}</sup> : null}
    </TabsPrimitive.Trigger>
  )
}

/** The count of what's showing, set huge and cropped by the rule it sinks into. Put it inside TabsList; it rolls when the number changes. */
function TabsCount({ children, className, ...props }: Omit<React.ComponentProps<"span">, "children"> & { children: number | string }) {
  const text = String(children)
  const inner = React.useRef<HTMLSpanElement>(null)
  const [shown, setShown] = React.useState(text)
  React.useEffect(() => {
    if (text === shown) return
    const el = inner.current
    if (!el) return setShown(text)
    roll(el, () => setShown(text), "100%", +text > +shown ? 1 : -1)
  }, [text, shown])
  return (
    <span data-slot="tabs-count" aria-hidden="true" className={cn("db-tabs-count", className)} {...props}>
      <span ref={inner}>{shown}</span>
    </span>
  )
}

function TabsContent({ className, ...props }: React.ComponentProps<typeof TabsPrimitive.Content>) {
  return <TabsPrimitive.Content data-slot="tabs-content" className={className} {...props} />
}

export { Tabs, TabsList, TabsTrigger, TabsContent, TabsCount }

@layer components {
  /* ── db-tabs ── words; a line slides under the one in view.
     Radix keeps the roving focus and the arrow keys; the line reads --x, --r, --y
     from the active tab (see tabs.tsx). */
  .db-tabs {
    position: relative; display: flex; flex-wrap: wrap; column-gap: var(--db-space-6); row-gap: var(--db-space-2);
    padding-block-end: var(--db-space-3);
    background: linear-gradient(var(--db-rule), var(--db-rule)) no-repeat 0 100% / 100% var(--db-hairline);
  }
  .db-tabs > [role="tab"] {
    appearance: none; border: 0; background: none; margin: 0; padding: 0; cursor: pointer;
    font-size: var(--db-mp); line-height: var(--db-mp-lh); color: var(--db-pencil);
    transition: color var(--db-allegro);
  }
  .db-tabs > [role="tab"]:is(:hover, [data-force~="hover"]) { color: var(--db-graphite); }
  .db-tabs > [role="tab"][data-state="active"] { color: var(--db-ink); }
  .db-tabs > [role="tab"]:disabled { cursor: not-allowed; opacity: 0.5; }
  .db-tabs sup { font-size: 0.5em; line-height: 0; vertical-align: 0.95em; margin-inline-start: 0.2em; font-variant-numeric: tabular-nums; color: var(--db-pencil); }
  .db-tabs-line {
    position: absolute; left: var(--x, 0px); right: var(--r, 100%); bottom: 0; height: var(--db-stroke);
    background: var(--db-ink); translate: 0 var(--y, 0px); pointer-events: none;
    transition: left var(--db-andante) var(--db-breath), right var(--db-andante) var(--db-breath), translate var(--db-moderato) var(--db-breath);
  }
  .db-tabs[data-dir="right"] .db-tabs-line { transition-delay: 110ms, 0s, 0s; }
  .db-tabs[data-dir="left"] .db-tabs-line { transition-delay: 0s, 110ms, 0s; }
  .db-tabs:not([data-ready]) .db-tabs-line { transition: none; }
  /* The count of what's showing, set huge and cropped by the rule it sinks into. */
  .db-tabs-count {
    position: absolute; inset-inline-end: 0; inset-block-end: 0; block-size: 0.56em; overflow: clip; pointer-events: none;
    font-size: clamp(5rem, 10vw, 9rem); font-weight: 100; font-stretch: 112%; line-height: 0.78; letter-spacing: -0.04em;
    color: var(--db-ink); font-variant-numeric: tabular-nums lining-nums;
  }
  .db-tabs-count > span { display: block; }
  @media (max-width: 700px) { .db-tabs-count { display: none; } }
  @media (max-width: 40rem) { .db-tabs { column-gap: var(--db-space-4); } } /* four words stay on one line at phone width, so the line has one row to sit under */
}
